var settings = new JsonSerializerSettings {
    TypeNameHandling = TypeNameHandling.Auto,      // writes "$type": "<assembly-qualified name>"
    SerializationBinder = new AllowListBinder(),   // deny by default, map tags to types
};
var evt = JsonConvert.DeserializeObject<Event>(payload, settings);

sealed class AllowListBinder : ISerializationBinder {
    public Type BindToType(string? assembly, string typeName) =>
        Allowed.TryGetValue(typeName, out var t) ? t : throw new JsonSerializationException(typeName);
}
